replace_once('src/trace_engine_v2/part_014a.inc', '      if (issue_1447_should_play_vessel_for_ready_turn() &&\n          play_earthen_vessel(true)) return true;\n      if (play_earthen_vessel(permit_payload)) return true;\n      if (play_quick_ball(permit_payload)) return true;\n', '      if (issue_1447_should_play_vessel_for_ready_turn() &&\n          play_earthen_vessel(true)) return true;\n      // Letter is the cheaper Energy-only connector because its printed effect has\n      // no discard cost. Keep Vessel first only when its mandatory discard can\n      // simultaneously establish the current-turn Dragon payload:\n      // Professor\'s Letter: https://api.pokemontcg.io/v2/cards/xy1-123\n      // Earthen Vessel: https://api.pokemontcg.io/v2/cards/sv4-163\n      // Regidrago VSTAR / Apex Dragon: https://api.pokemontcg.io/v2/cards/swsh12-136\n      // https://github.com/FlareZ123/pokemon-sims/blob/main/docs/POLICY_DECISIONS.md#decision-priorities\n      // https://github.com/FlareZ123/pokemon-sims/issues/2509\n      const bool vessel_payload_compression_live =\n          permit_payload && need_payload() && can_play_payload_this_turn() &&\n          hand_count(Card::EarthenVessel) > 0 &&\n          std::any_of(state_.hand.begin(), state_.hand.end(), is_payload);\n      if (!vessel_payload_compression_live && play_professors_letter()) return true;\n      if (play_earthen_vessel(permit_payload)) return true;\n      if (play_professors_letter()) return true;\n      if (play_quick_ball(permit_payload)) return true;\n')
replace_once('README.md', 'The validation matrix in [`docs/BATTLE_VIP_PASS_VALIDATION.md`](docs/BATTLE_VIP_PASS_VALIDATION.md) uses an unregistered temporary shell derivative with `-1 Quick Ball`, `-1 Mysterious Treasure`, and `+2 Battle VIP Pass`. The temporary recipe is excluded from `deck_registry()` and `--all-decks`.\n\n## Run one readable hand\n', 'The validation matrix in [`docs/BATTLE_VIP_PASS_VALIDATION.md`](docs/BATTLE_VIP_PASS_VALIDATION.md) uses an unregistered temporary shell derivative with `-1 Quick Ball`, `-1 Mysterious Treasure`, and `+2 Battle VIP Pass`. The temporary recipe is excluded from `deck_registry()` and `--all-decks`.\n\n## Professor\'s Letter paper Expanded model\n\nProfessor\'s Letter `xy1-123` is modeled as a paper-Expanded Item that searches up to two Basic Energy into hand and has no discard cost. It establishes K1 through the physical deck search and is held when the Energy axis is already complete. It is intentionally absent from both registered Pokémon TCG Live recipes. CI evaluates an unregistered temporary `regidrago-shell` derivative with exactly `-2 Earthen Vessel` and `+2 Professor\'s Letter`, using matched scenario seeds and checkpoint metrics for Regidrago, VSTAR, Active position, semantic Apex Energy, current-turn payload, and K1. Professor\'s Letter: https://api.pokemontcg.io/v2/cards/xy1-123 ; enhancement: https://github.com/FlareZ123/pokemon-sims/issues/2509\n\n## Run one readable hand\n')
