(ROOT / 'tests/issue_2509_professors_letter_tests.cpp').write_text('#define REGIDRAGO_SIM_NO_MAIN\n#include "../src/regidrago_sim.cpp"\n\n#include <algorithm>\n#include <numeric>\n#include <random>\n#include <stdexcept>\n\nnamespace sim {\nstruct EngineTestAccess {\n  static void set_state(Engine& engine, State state) {\n    engine.state_ = std::move(state);\n  }\n  static const State& state(const Engine& engine) { return engine.state_; }\n  static bool play_professors_letter(Engine& engine) {\n    return engine.play_professors_letter();\n  }\n  static bool deck_seen(const Engine& engine) { return engine.deck_seen_; }\n  static void set_deck_seen(Engine& engine, const bool value) {\n    engine.deck_seen_ = value;\n  }\n};\n}  // namespace sim\n\nnamespace {\nvoid expect(const bool condition, const char* message) {\n  if (!condition) throw std::runtime_error(message);\n}\n\nint count_card(const std::vector<sim::Card>& zone, const sim::Card card) {\n  return static_cast<int>(std::count(zone.begin(), zone.end(), card));\n}\n\nsim::State live_letter_state() {\n  sim::State state;\n  state.turn = 2;\n  state.active = sim::Pokemon{sim::Card::RegidragoVstar, 1};\n  state.active->fire = 1;\n  state.hand = {sim::Card::ProfessorsLetter, sim::Card::MegaDragonite};\n  state.deck = {sim::Card::Grass, sim::Card::Grass, sim::Card::Fire};\n  return state;\n}\n\nvoid test_professors_letter_searches_two_basic_energy_without_discard_cost() {\n  sim::Scenario scenario{"issue-2509", sim::DciProfile::StrictJit,\n                         sim::LockMode::None, false, 4};\n  sim::DeckRecipe recipe = sim::baseline_recipe();\n  recipe.push_back({sim::Card::ProfessorsLetter, 1});\n  std::mt19937_64 rng{2509};\n  sim::Engine engine(scenario, recipe, rng);\n  sim::EngineTestAccess::set_state(engine, live_letter_state());\n\n  expect(sim::EngineTestAccess::play_professors_letter(engine),\n         "Professor\'s Letter did not resolve with live Basic Energy targets");\n  const sim::State& state = sim::EngineTestAccess::state(engine);\n\n  // Professor\'s Letter searches up to two Basic Energy and has no discard cost:\n  // https://api.pokemontcg.io/v2/cards/xy1-123\n  // https://www.pokemon.com/us/pokemon-tcg/pokemon-cards/series/xy1/123/\n  // Core Item/search procedure: https://www.pokemon.com/us/pokemon-tcg/rules\n  // Enhancement: https://github.com/FlareZ123/pokemon-sims/issues/2509\n  expect(count_card(state.hand, sim::Card::Grass) == 2,\n         "Professor\'s Letter did not take both legal same-type Basic Energy");\n  expect(count_card(state.hand, sim::Card::MegaDragonite) == 1,\n         "Professor\'s Letter incorrectly discarded another hand card");\n  expect(count_card(state.discard, sim::Card::ProfessorsLetter) == 1,\n         "Professor\'s Letter did not enter discard after resolution");\n  expect(count_card(state.discard, sim::Card::MegaDragonite) == 0,\n         "Professor\'s Letter invented Earthen Vessel\'s discard cost");\n  expect(sim::EngineTestAccess::deck_seen(engine),\n         "Professor\'s Letter deck search did not establish K1");\n}\n\nvoid test_professors_letter_respects_item_lock_and_energy_value() {\n  sim::DeckRecipe recipe = sim::baseline_recipe();\n  recipe.push_back({sim::Card::ProfessorsLetter, 1});\n\n  sim::Scenario locked{"issue-2509-lock", sim::DciProfile::StrictJit,\n                       sim::LockMode::FullItem, false, 4};\n  std::mt19937_64 locked_rng{2509};\n  sim::Engine locked_engine(locked, recipe, locked_rng);\n  sim::EngineTestAccess::set_state(locked_engine, live_letter_state());\n  expect(!sim::EngineTestAccess::play_professors_letter(locked_engine),\n         "Professor\'s Letter ignored Item lock");\n\n  sim::Scenario open{"issue-2509-complete", sim::DciProfile::StrictJit,\n                     sim::LockMode::None, false, 4};\n  std::mt19937_64 open_rng{2510};\n  sim::Engine complete_engine(open, recipe, open_rng);\n  sim::State complete = live_letter_state();\n  complete.active->grass = 2;\n  sim::EngineTestAccess::set_state(complete_engine, complete);\n  expect(!sim::EngineTestAccess::play_professors_letter(complete_engine),\n         "Professor\'s Letter was burned after the Energy axis was complete");\n}\n\nvoid test_professors_letter_k1_rejects_exhausted_needed_energy() {\n  sim::Scenario scenario{"issue-2509-k1", sim::DciProfile::StrictJit,\n                         sim::LockMode::None, false, 4};\n  sim::DeckRecipe recipe = sim::baseline_recipe();\n  recipe.push_back({sim::Card::ProfessorsLetter, 1});\n  std::mt19937_64 rng{2511};\n  sim::Engine engine(scenario, recipe, rng);\n  sim::State state = live_letter_state();\n  state.deck = {sim::Card::Fire};\n  sim::EngineTestAccess::set_state(engine, state);\n  sim::EngineTestAccess::set_deck_seen(engine, true);\n  expect(!sim::EngineTestAccess::play_professors_letter(engine),\n         "K1 played Professor\'s Letter after all needed Grass was absent");\n}\n\nvoid test_professors_letter_is_not_a_registered_deck_card() {\n  // The user-requested comparison is an unregistered paper-Expanded derivative:\n  // https://api.pokemontcg.io/v2/cards/xy1-123\n  // https://github.com/FlareZ123/pokemon-sims/issues/2509\n  expect(sim::deck_registry().size() == 2U,\n         "Professor\'s Letter changed the named-deck registry");\n  for (const sim::NamedDeck& deck : sim::deck_registry()) {\n    const int copies = std::accumulate(\n        deck.recipe.begin(), deck.recipe.end(), 0,\n        [](const int total, const auto& entry) {\n          return total +\n              (entry.first == sim::Card::ProfessorsLetter ? entry.second : 0);\n        });\n    expect(copies == 0, "Professor\'s Letter leaked into a registered recipe");\n  }\n}\n}  // namespace\n\nint main() {\n  test_professors_letter_searches_two_basic_energy_without_discard_cost();\n  test_professors_letter_respects_item_lock_and_energy_value();\n  test_professors_letter_k1_rejects_exhausted_needed_energy();\n  test_professors_letter_is_not_a_registered_deck_card();\n}\n', encoding='utf-8')
(ROOT / 'tools/professors_letter_swap_matrix.cpp').write_text('#define REGIDRAGO_SIM_NO_MAIN\n#include "../src/regidrago_sim.cpp"\n\n#include <array>\n#include <cstdint>\n#include <fstream>\n#include <iomanip>\n#include <iostream>\n#include <random>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\nnamespace sim {\n\nstruct SetupCheckpoint {\n  bool regi{false};\n  bool vstar{false};\n  bool active_vstar{false};\n  bool energy{false};\n  bool payload{false};\n  bool k1{false};\n};\n\nstruct CheckpointTrial {\n  TrialOutcome outcome;\n  std::array<SetupCheckpoint, 5> by_turn{};\n};\n\nstruct EngineTestAccess {\n  static SetupCheckpoint checkpoint(Engine& engine) {\n    const Pokemon* target = engine.target_regi();\n    return {\n        engine.in_play(Card::RegidragoV) ||\n            engine.in_play(Card::RegidragoVstar),\n        engine.in_play(Card::RegidragoVstar),\n        engine.active_is_vstar(),\n        target != nullptr && engine.pays_apex_energy_cost(*target),\n        engine.payload_ready(),\n        engine.prizes_known(),\n    };\n  }\n\n  static CheckpointTrial run(Engine& engine) {\n    CheckpointTrial result;\n    engine.setup();\n    SetupCheckpoint latest;\n    for (int next_turn = 1; next_turn <= engine.scenario_.max_turn; ++next_turn) {\n      engine.begin_turn(next_turn);\n      if (engine.state_.turn_ended) break;\n      engine.run_turn();\n      engine.record_ready();\n      latest = checkpoint(engine);\n      result.by_turn[static_cast<std::size_t>(next_turn - 1)] = latest;\n      if (engine.outcome_.first_ready_turn != 0) {\n        for (int future = next_turn + 1; future <= 5; ++future) {\n          result.by_turn[static_cast<std::size_t>(future - 1)] = latest;\n        }\n        break;\n      }\n      engine.resolve_powerglass_end_turn();\n    }\n    result.outcome = engine.outcome_;\n    return result;\n  }\n};\n\nstruct VariantAggregate {\n  std::uint64_t trials{0};\n  std::uint64_t by2{0};\n  std::uint64_t by3{0};\n  std::uint64_t by4{0};\n  std::array<std::uint64_t, 5> regi{};\n  std::array<std::uint64_t, 5> vstar{};\n  std::array<std::uint64_t, 5> active_vstar{};\n  std::array<std::uint64_t, 5> energy{};\n  std::array<std::uint64_t, 5> payload{};\n  std::array<std::uint64_t, 5> k1{};\n};\n\nDeckRecipe professors_letter_swap_recipe() {\n  DeckRecipe recipe = baseline_recipe();\n  const auto vessel = std::find_if(\n      recipe.begin(), recipe.end(),\n      [](const auto& entry) { return entry.first == Card::EarthenVessel; });\n  if (vessel == recipe.end() || vessel->second != 2) {\n    throw std::logic_error(\n        "regidrago-shell no longer has exactly two Earthen Vessel");\n  }\n  recipe.erase(vessel);\n  recipe.push_back({Card::ProfessorsLetter, 2});\n\n  NamedDeck validation{"professors-letter-temporary-swap", recipe};\n  std::string error;\n  if (!validate_recipe(validation, &error)) throw std::logic_error(error);\n\n  // This is intentionally an unregistered paper-Expanded derivative:\n  // Professor\'s Letter: https://api.pokemontcg.io/v2/cards/xy1-123\n  // Earthen Vessel: https://api.pokemontcg.io/v2/cards/sv4-163\n  // Enhancement: https://github.com/FlareZ123/pokemon-sims/issues/2509\n  return recipe;\n}\n\nVariantAggregate simulate_checkpoints(\n    const Scenario& scenario, const DeckRecipe& recipe,\n    const std::uint64_t trials, const std::uint64_t seed) {\n  std::mt19937_64 rng(seed);\n  VariantAggregate aggregate;\n  for (std::uint64_t trial = 0; trial < trials; ++trial) {\n    Engine engine(scenario, recipe, rng);\n    const CheckpointTrial result = EngineTestAccess::run(engine);\n    ++aggregate.trials;\n    aggregate.by2 += result.outcome.ready_by_2 ? 1U : 0U;\n    aggregate.by3 += result.outcome.ready_by_3 ? 1U : 0U;\n    aggregate.by4 += result.outcome.ready_by_4 ? 1U : 0U;\n    for (std::size_t turn = 0; turn < aggregate.regi.size(); ++turn) {\n      aggregate.regi[turn] += result.by_turn[turn].regi ? 1U : 0U;\n      aggregate.vstar[turn] += result.by_turn[turn].vstar ? 1U : 0U;\n      aggregate.active_vstar[turn] +=\n          result.by_turn[turn].active_vstar ? 1U : 0U;\n      aggregate.energy[turn] += result.by_turn[turn].energy ? 1U : 0U;\n      aggregate.payload[turn] += result.by_turn[turn].payload ? 1U : 0U;\n      aggregate.k1[turn] += result.by_turn[turn].k1 ? 1U : 0U;\n    }\n  }\n  return aggregate;\n}\n\ndouble percent(const std::uint64_t count, const std::uint64_t total) {\n  return total == 0 ? 0.0 :\n      100.0 * static_cast<double>(count) / static_cast<double>(total);\n}\n\nvoid write_row(std::ostream& out, const std::string& variant,\n               const Scenario& scenario, const VariantAggregate& a) {\n  out << variant << \',\' << scenario.label << \',\' << a.trials << \',\'\n      << std::fixed << std::setprecision(6)\n      << percent(a.by2, a.trials) << \',\'\n      << percent(a.by3, a.trials) << \',\'\n      << percent(a.by4, a.trials);\n  for (const std::size_t index : {1U, 2U, 3U}) {\n    out << \',\' << percent(a.regi[index], a.trials)\n        << \',\' << percent(a.vstar[index], a.trials)\n        << \',\' << percent(a.active_vstar[index], a.trials)\n        << \',\' << percent(a.energy[index], a.trials)\n        << \',\' << percent(a.payload[index], a.trials)\n        << \',\' << percent(a.k1[index], a.trials);\n  }\n  out << \'\\n\';\n}\n\n}  // namespace sim\n\nint main(int argc, char** argv) {\n  if (argc != 4) {\n    std::cerr << "usage: professors_letter_swap_matrix TRIALS SEED OUTPUT\\n";\n    return 2;\n  }\n  const std::uint64_t trials = std::stoull(argv[1]);\n  const std::uint64_t seed = std::stoull(argv[2]);\n  if (trials == 0) throw std::runtime_error("TRIALS must be positive");\n\n  const sim::DeckRecipe baseline = sim::baseline_recipe();\n  const sim::DeckRecipe letter = sim::professors_letter_swap_recipe();\n  std::ofstream out(argv[3], std::ios::binary | std::ios::trunc);\n  if (!out) throw std::runtime_error("could not open output");\n\n  out << "variant,scenario,trials,ready_by_t2_pct,ready_by_t3_pct,"\n         "ready_by_t4_pct,"\n         "t2_regi_pct,t2_vstar_pct,t2_active_vstar_pct,t2_energy_pct,"\n         "t2_payload_pct,t2_k1_pct,"\n         "t3_regi_pct,t3_vstar_pct,t3_active_vstar_pct,t3_energy_pct,"\n         "t3_payload_pct,t3_k1_pct,"\n         "t4_regi_pct,t4_vstar_pct,t4_active_vstar_pct,t4_energy_pct,"\n         "t4_payload_pct,t4_k1_pct\\n";\n\n  const std::vector<sim::Scenario> scenarios = sim::all_scenarios();\n  for (std::size_t index = 0; index < scenarios.size(); ++index) {\n    const std::size_t seed_slot =\n        index + (index >= 4 ? 1U : 0U) + (index >= 10 ? 1U : 0U);\n    const std::uint64_t common_seed = seed + 104729ULL * seed_slot;\n    const sim::VariantAggregate baseline_result =\n        sim::simulate_checkpoints(\n            scenarios[index], baseline, trials, common_seed);\n    const sim::VariantAggregate letter_result =\n        sim::simulate_checkpoints(\n            scenarios[index], letter, trials, common_seed);\n    sim::write_row(\n        out, "regidrago-shell", scenarios[index], baseline_result);\n    sim::write_row(out, "letter-swap", scenarios[index], letter_result);\n  }\n  return 0;\n}\n', encoding='utf-8')

